CREATE DATABASE IF NOT EXISTS tiktok_agency CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tiktok_agency;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS sync_logs,tiktok_tokens,live_sessions,contents,products,campaigns,creators,agencies,users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('admin','staff') NOT NULL DEFAULT 'staff',is_active TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE agencies(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,contact_email VARCHAR(190),status VARCHAR(30) DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE creators(id INT AUTO_INCREMENT PRIMARY KEY,agency_id INT NULL,name VARCHAR(160) NOT NULL,tiktok_username VARCHAR(100),status VARCHAR(30) DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(agency_id) REFERENCES agencies(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE campaigns(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,start_date DATE NULL,end_date DATE NULL,budget DECIMAL(16,2) DEFAULT 0,target_views BIGINT DEFAULT 0,status VARCHAR(30) DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE contents(id BIGINT AUTO_INCREMENT PRIMARY KEY,creator_id INT NULL,tiktok_video_id VARCHAR(80) UNIQUE,title VARCHAR(255),description TEXT,cover_url TEXT,share_url TEXT,duration INT DEFAULT 0,views BIGINT DEFAULT 0,likes BIGINT DEFAULT 0,comments BIGINT DEFAULT 0,shares BIGINT DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,tiktok_created_at DATETIME NULL,FOREIGN KEY(creator_id) REFERENCES creators(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,sku VARCHAR(80),category VARCHAR(100),price DECIMAL(16,2) DEFAULT 0,status VARCHAR(30) DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE live_sessions(id BIGINT AUTO_INCREMENT PRIMARY KEY,creator_id INT NULL,title VARCHAR(255),started_at DATETIME NULL,ended_at DATETIME NULL,viewers_peak BIGINT DEFAULT 0,likes BIGINT DEFAULT 0,gmv DECIMAL(18,2) DEFAULT 0,status VARCHAR(30) DEFAULT 'unknown',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(creator_id) REFERENCES creators(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE tiktok_tokens(id BIGINT AUTO_INCREMENT PRIMARY KEY,open_id VARCHAR(150),access_token TEXT NOT NULL,refresh_token TEXT,expires_at DATETIME,refresh_expires_at DATETIME,scope TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE sync_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,status VARCHAR(20),message TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
